package com.haolin.vontlocal;
import android.app.*;import android.os.*;import android.text.*;import android.view.*;import android.view.inputmethod.*;import android.widget.*;
/** Preset editor: none of these controls sends a device command. */
public final class SleepActivity extends Activity {
    Ui u;String scene;EditText warm1,warm2,brightness,temperature,minutes;TextView saved,focusSummary;boolean dirty;
    @Override public void onCreate(Bundle state){Ui.prepare(this);super.onCreate(state);String id=getIntent().getStringExtra("sceneId");scene=SceneStore.id(id==null?"bed":id);u=new Ui(this);LinearLayout root=u.root(this);u.toolbar(this,root,"编辑 · "+LinkPolicy.name(scene),"保存后，下次点按场景时使用");LinearLayout body=u.scrollBody(root);LinkPolicy.Settings s=SceneStore.settings(this,scene);
        LinearLayout intro=u.card(body);u.text(intro,SceneStore.mood(scene),22);u.hint(intro,LinkPolicy.bed(scene)?"两组暖光就绪后，开始灯内倒计时。":"只留挂灯持续照明，Vont 关闭，并取消两组旧倒计时。");
        LinearLayout lamp=u.card(body);u.text(lamp,"屏幕挂灯",20);brightness=numeric(lamp,"亮度","场景挂灯亮度",s.brightness,1,100,"%");temperature=numeric(lamp,"色温","场景挂灯色温",s.temperature,2700,6500,"K");u.hint(lamp,"2700K 更暖黄  ·  6500K 更冷白");
        if(LinkPolicy.bed(scene)){LinearLayout vont=u.card(body);u.text(vont,"Vont 双灯暖光",20);u.hint(vont,"两路暖光独立调节，数值沿用设备的 1–100。");warm1=numeric(vont,"通道 1","场景Vont通道1",s.warm1,1,100,"");warm2=numeric(vont,"通道 2","场景Vont通道2",s.warm2,1,100,"");LinearLayout timer=u.card(body);u.text(timer,"多久后，一起关灯",20);minutes=numeric(timer,"时长","场景关灯分钟",s.minutes,10,60,"分钟");LinearLayout quick=u.row();for(int m:new int[]{10,15,30,60})u.button(quick,String.valueOf(m),()->minutes.setText(String.valueOf(m)),false);timer.addView(quick);u.hint(timer,"手机无需常驻。米家原有规则仍可能提前改变挂灯。");}
        if("work".equals(scene)){LinearLayout focus=u.card(body);u.text(focus,"提醒休息",21);focusSummary=u.hint(focus,FocusStore.detail(this));u.hint(focus,"按需开启，确认前不改变灯光。工作、休息时长和休息光都可单独保存。");u.button(focus,"设置提醒参数",()->startActivity(new android.content.Intent(this,FocusSettingsActivity.class)),false);u.button(focus,"开始本次专注",()->{if(dirty){Toast.makeText(this,"请先保存办公场景的修改",1).show();return;}FocusConfirmActivity.open(this);},true);}
        saved=u.hint(body,"保存不会改变当前灯光或正在运行的倒计时。");LinearLayout bottom=u.column();bottom.setPadding(u.dp(this,20),u.dp(this,8),u.dp(this,20),u.dp(this,12));u.button(bottom,"保存"+LinkPolicy.name(scene)+"场景",()->save(s),true);root.addView(bottom);
        if(state!=null){restore(brightness,state,"b");restore(temperature,state,"k");restore(warm1,state,"w1");restore(warm2,state,"w2");restore(minutes,state,"m");dirty=state.getBoolean("dirty");}else dirty=false;
    }
    EditText numeric(LinearLayout parent,String name,String desc,int value,int low,int high,String unit){LinearLayout line=u.row();line.addView(u.label(name,16,u.text),new LinearLayout.LayoutParams(0,-2,1));EditText field=new EditText(this);field.setTextSize(18);field.setTextColor(u.accent);field.setGravity(Gravity.END);field.setSingleLine(true);field.setSelectAllOnFocus(true);field.setInputType(InputType.TYPE_CLASS_NUMBER);field.setImeOptions(EditorInfo.IME_ACTION_DONE);field.setContentDescription(desc);field.setText(String.valueOf(value));line.addView(field,new LinearLayout.LayoutParams(u.dp(this,104),u.dp(this,50)));line.addView(u.label(" "+unit,13,u.muted));parent.addView(line);SeekBar seek=new SeekBar(this);seek.setMax(high-low);seek.setProgress(value-low);seek.setContentDescription(desc+"滑块");parent.addView(seek,new LinearLayout.LayoutParams(-1,u.dp(this,48)));u.styleTree(seek);
        seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){if(user)field.setText(String.valueOf(low+n));}});
        field.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int count){dirty=true;try{int n=Integer.parseInt(s.toString());if(n>=low&&n<=high)seek.setProgress(n-low);}catch(Exception ignored){}}});field.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_DONE){hideKeyboard();field.clearFocus();return true;}return false;});return field;
    }
    void hideKeyboard(){View f=getCurrentFocus();if(f!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(f.getWindowToken(),0);}
    void save(LinkPolicy.Settings old){try{LinkPolicy.Settings s=new LinkPolicy.Settings(warm1==null?old.warm1:input(warm1,1,100),warm2==null?old.warm2:input(warm2,1,100),input(brightness,1,100),input(temperature,2700,6500),minutes==null?old.minutes:input(minutes,10,60));SceneStore.save(this,scene,s);hideKeyboard();dirty=false;Toast.makeText(this,"已保存，下一次使用",0).show();finish();}catch(IllegalArgumentException e){saved.setText(e.getMessage());saved.setTextColor(u.accent);}}
    int input(EditText f,int low,int high){return LinkPolicy.integer(f.getText().toString(),low,high);}
    void restore(EditText f,Bundle b,String k){if(f!=null&&b.containsKey(k))f.setText(b.getString(k));}
    void put(Bundle b,String k,EditText f){if(f!=null)b.putString(k,f.getText().toString());}
    @Override public void onResume(){super.onResume();if(focusSummary!=null)focusSummary.setText(FocusStore.detail(this));}
    @Override public void onSaveInstanceState(Bundle b){put(b,"b",brightness);put(b,"k",temperature);put(b,"w1",warm1);put(b,"w2",warm2);put(b,"m",minutes);b.putBoolean("dirty",dirty);super.onSaveInstanceState(b);}
    @Override public void onBackPressed(){if(!dirty){super.onBackPressed();return;}new AlertDialog.Builder(this).setTitle("还没有保存").setMessage("离开会丢弃这次修改。").setNegativeButton("继续编辑",null).setPositiveButton("放弃修改",(d,w)->finish()).show();}
}
